<?php namespace AISEO\Admin; class Bulk_Queue { public function enqueue(array $product_ids,string $task):void{ foreach($product_ids as $pid){ wp_schedule_single_event(time(),"ai_seo_bulk_{$task}",[$pid]); } } public function process(int $pid,string $task){ $gen=new \AISEO\WooCommerce\WC_AI_Generator(); $res=$gen->generate_description($pid); update_post_meta($pid,'_ai_seo_bulk_result',$res); } }
